(() => {
  'use strict';
  const KEY = 'rollcall.web.v1';
  const blank = () => ({version:1,target:75,name:'',courses:[],schedule:[],ods:[],history:[],academicRecords:[],internalMarks:[],exams:[],academicUpdatedAt:0,settings:{dark:false,appearance:'system',palette:'signal',reminders:false}});
  let data = blank(), screen = 'home', courseFilter = 'all', courseQuery = '', odFilter = 'current', weekShift = 0, selectedDay = 0, remoteMode = false;
  let settingsStack = ['root'], settingsDirection = 'forward', settingsTouchX = null, modePulling = false, reminderTimer = 0, notificationRegistration = null;
  const main = document.querySelector('#main');
  const screens = {home:'Home',courses:'Courses',week:'Week','whatif':'What if?','od':'Leave & OD',marks:'Marks',settings:'Settings'};
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num = value => Number.isFinite(Number(value)) ? Number(value) : 0;
  const coursePercent = c => c.total > 0 ? Math.round(100 * c.attended / c.total * 10) / 10 : null;
  const fmtPct = n => n == null ? '—' : `${Math.round(n * 10) / 10}%`;
  const dayKey = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const parseDay = s => { const [y,m,d] = String(s).split('-').map(Number); return new Date(y,(m||1)-1,d||1,12); };
  const fmtDay = s => parseDay(s).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});
  const fmtRange = (a,b) => a === b ? fmtDay(a) : `${fmtDay(a)} – ${fmtDay(b)}`;
  const startWeek = (shift=0) => { const d = new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate()-d.getDay()+shift*7); return d; };
  const normalize = input => {
    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('The backup needs to be a Rollcall data object.');
    const rows = Array.isArray(input.courses) ? input.courses : [];
    const internalRows = new Map();
    for (const row of (Array.isArray(input.internalMarks) ? input.internalMarks.slice(0,2000) : [])) {
      if (!row || typeof row !== 'object') continue;
      const course=String(row.course||row.name||'').trim().slice(0,100), assessment=String(row.assessment||row.exam||'').trim().slice(0,100);
      if (!course || !assessment) continue;
      const score=Number(row.score??row.marks), maximum=Number(row.maximum??row.maxMarks), scoreAvailable=Number.isFinite(score)&&Number.isFinite(maximum)&&maximum>0&&maximum<=10000&&score>=0&&score<=maximum;
      let status=String(row.status||(scoreAvailable?'published':'unpublished')).toLowerCase();
      if (!['published','unpublished','withheld','missing'].includes(status)||status==='published'&&!scoreAvailable) status='unpublished';
      const published=status==='published';
      const semester=String(row.semester||'').slice(0,80), courseCode=String(row.courseCode||row.code||'').slice(0,40), date=String(row.date||'').slice(0,40);
      const id=String(row.assessmentId||row.id||`${semester}|${courseCode}|${course}|${assessment}|${date}`).slice(0,120);
      internalRows.set(id,{id,semester,courseCode,course,assessment,score:published?score:null,maximum:published?maximum:null,scoreAvailable:published,status,date,publishedAt:String(row.publishedAt||'').slice(0,40),source:String(row.source||'KCT').slice(0,80),lastSyncedAt:Math.max(0,num(row.lastSyncedAt))});
    }
    const internalMarks=[...internalRows.values()];
    const courses = rows.slice(0,300).map(c => {
      if (!c || typeof c !== 'object') throw new Error('A course in the backup is unreadable.');
      const attended = num(c.attended), total = num(c.total), name = String(c.name || '').trim();
      if (!name || name.length > 100 || !Number.isInteger(attended) || !Number.isInteger(total) || attended < 0 || total < attended || total > 100000) throw new Error('A course has invalid counts or a missing name.');
      return {id:String(c.id || crypto.randomUUID()),name,code:String(c.code||'').slice(0,40),attended,total};
    });
    const schedule = Array.isArray(input.schedule) ? input.schedule.slice(0,1000).map(e => ({id:String(e.id||crypto.randomUUID()),date:String(e.date||''),time:String(e.time||''),endTime:String(e.endTime||''),name:String(e.name||'Class').slice(0,100),code:String(e.code||'').slice(0,40),location:String(e.location||'').slice(0,80)})) : [];
    const ods = Array.isArray(input.ods) ? input.ods.slice(0,500).map(o => {
      const hours = num(o.hours);
      if (!o.start || !o.end || hours < 0 || hours > 120) throw new Error('An OD record has invalid dates or hours.');
      return {id:String(o.id||crypto.randomUUID()),type:o.type==='Leave'?'Leave':'On Duty',status:['Approved','Pending','Rejected'].includes(o.status)?o.status:'Pending',start:String(o.start),end:String(o.end),hours,currentSemester:o.currentSemester!==false,details:Array.isArray(o.details)?o.details.slice(0,1000).map(d=>({date:String(d.date||''),period:num(d.period),time:String(d.time||''),endTime:String(d.endTime||''),name:String(d.name||''),code:String(d.code||'')})):[]};
    }) : [];
    const target = num(input.target ?? 75);
    if (target < 1 || target > 100) throw new Error('The attendance target must be between 1% and 100%.');
    return {version:1,target,name:String(input.name||'').slice(0,60),courses,schedule,ods,history:Array.isArray(input.history)?input.history.slice(0,2000):[],academicRecords:Array.isArray(input.academicRecords)?input.academicRecords:[],internalMarks,exams:Array.isArray(input.exams)?input.exams:[],settings:{dark:!!input.settings?.dark,appearance:['system','dark','light'].includes(input.settings?.appearance)?input.settings.appearance:input.settings?.dark?'dark':'light',palette:['signal','cobalt','copper','forest','paper'].includes(input.settings?.palette)?input.settings.palette:'signal',reminders:input.settings?.reminders===true,mycamuImportedAt:String(input.settings?.mycamuImportedAt||'')}};
  };
  function save(){ if(remoteMode){try{const local=JSON.parse(localStorage.getItem(KEY)||'{}');local.settings=local.settings&&typeof local.settings==='object'?local.settings:{};Object.assign(local.settings,{dark:data.settings.dark,appearance:data.settings.appearance,palette:data.settings.palette});localStorage.setItem(KEY,JSON.stringify(local));}catch(error){console.warn('Rollcall appearance preference could not be saved.',error);}updateChrome();return;} localStorage.setItem(KEY,JSON.stringify(data)); updateChrome(); scheduleClassReminder(); }
  function load(){ try{ const raw=localStorage.getItem(KEY); if(raw)data=normalize(JSON.parse(raw)); }catch(e){ data=blank(); console.warn('Rollcall local data could not be loaded.',e); } }
  function isDarkMode(){return data.settings.appearance==='system'?matchMedia('(prefers-color-scheme: dark)').matches:data.settings.appearance==='dark';}
  function updateChrome(){
    const dark=isDarkMode();data.settings.dark=dark;document.body.classList.toggle('dark',dark);
    document.body.dataset.palette=data.settings.palette||'signal';
    const current=document.querySelector('#crumb-current'); if(current)current.textContent=screens[screen];
    document.querySelectorAll('[data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));
    document.querySelector('#profile-name').textContent=data.name||'My Rollcall';
    document.querySelector('#avatar').textContent=(data.name||'R').trim().slice(0,1).toUpperCase();
    const dot=document.querySelector('#connection-label'); dot.textContent=remoteMode?'Phone synced':data.settings.mycamuImportedAt?'MyCamu snapshot':'Local data';
    document.querySelector('#save-label').textContent=remoteMode?`Updated ${new Date(data.settings.mycamuImportedAt).toLocaleString()}`:data.settings.mycamuImportedAt?`Snapshot ${new Date(data.settings.mycamuImportedAt).toLocaleString()}`:'Saved in this browser';
    document.querySelector('#data-footnote').textContent=remoteMode?'Read-only snapshot from your Rollcall phone.':'Your data stays in this browser.';
  }
  function setScreen(next){ if(next==='settings'&&screen!=='settings')settingsStack=['root'];screen=next; updateChrome(); render(); main.focus({preventScroll:true}); window.scrollTo({top:0,behavior:'smooth'}); }
  function button(label,cls,attrs=''){return `<button class="button ${cls}" ${attrs}>${label}</button>`;}
  function sectionHead(title,action='',target=''){return `<div class="panel-head"><h2>${title}</h2>${action?`<button class="panel-link" data-go="${target}">${action} →</button>`:''}</div>`;}
  function safeMiss(c){return c.total?Math.max(0,Math.floor((100*c.attended-data.target*c.total)/data.target)):null;}
  function recover(c){if(data.target>=100)return c.attended>=c.total?0:Infinity;return c.total?Math.max(0,Math.ceil((data.target*c.total-100*c.attended)/(100-data.target))):null;}
  function courseStatus(c){const p=coursePercent(c);return p==null?'No classes recorded':p>=data.target?'On target':'Below target';}
  function statusClass(c){const p=coursePercent(c);return p==null?'':p>=data.target?'safe-text':'risk-text';}
  function targetBanner(){return `<span class="target-chip">${data.target}% target</span>`;}
  function remindersOn(){return data.settings.reminders&&'Notification'in window&&Notification.permission==='granted';}
  function nextTimedClass(){const now=new Date();return data.schedule.map(e=>({event:e,start:e.date&&e.time?new Date(`${e.date}T${e.time}`):null})).filter(x=>x.start&&!Number.isNaN(x.start.getTime())&&x.start>now).sort((a,b)=>a.start-b.start)[0]||null;}
  function scheduleClassReminder(){clearTimeout(reminderTimer);if(!remindersOn())return;const next=nextTimedClass();if(!next)return;const notifyAt=next.start.getTime()-10*60*1000,delay=Math.max(0,notifyAt-Date.now());reminderTimer=setTimeout(async()=>{if(Date.now()<notifyAt){scheduleClassReminder();return;}const body=`${next.event.name} starts at ${next.event.time}.`;try{if(notificationRegistration?.showNotification)await notificationRegistration.showNotification('Class in 10 minutes',{body,icon:'assets/rollcall-brush.png',tag:`rollcall-${next.event.id}`});else new Notification('Class in 10 minutes',{body,tag:`rollcall-${next.event.id}`});}catch(error){console.warn('Class reminder could not be shown.',error);}reminderTimer=setTimeout(scheduleClassReminder,Math.max(1000,next.start.getTime()-Date.now()+1000));},Math.min(delay,2147480000));}
  function holdButton(label,action,id,accessible){return `<button class="hold-action" type="button" data-hold-action="${action}" ${id?`data-id="${esc(id)}"`:''} aria-label="${esc(accessible||label)}"><span class="hold-fill" aria-hidden="true"></span><span class="hold-label">${label}</span></button>`;}
  function toggleTheme(button){const rect=button.getBoundingClientRect();document.documentElement.style.setProperty('--theme-x',`${rect.left+rect.width/2}px`);document.documentElement.style.setProperty('--theme-y',`${rect.top+rect.height/2}px`);modePulling=true;data.settings.appearance=isDarkMode()?'light':'dark';data.settings.dark=data.settings.appearance==='dark';const commit=()=>{save();render();};if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(commit);else commit();setTimeout(()=>{modePulling=false;main.querySelectorAll('[data-pulling]').forEach(el=>el.dataset.pulling='false');},500);}
  async function enableNotifications(button){const feedback=main.querySelector('#notification-feedback');if(!('Notification'in window)){if(feedback)feedback.textContent='This browser does not support notifications.';return;}if(!window.isSecureContext){if(feedback)feedback.textContent='Notifications require Rollcall to be open on HTTPS or localhost.';return;}button.disabled=true;try{const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();if(permission!=='granted'){if(feedback)feedback.textContent=permission==='denied'?'Notifications are blocked. Allow them in this site’s browser settings, then try again.':'Notification permission was not granted.';button.disabled=false;return;}data.settings.reminders=true;save();render();}catch(error){if(feedback)feedback.textContent='The browser could not enable notifications. Check this site’s permission settings.';button.disabled=false;}}
  function completeHold(button){const id=button.dataset.id;switch(button.dataset.holdAction){case'delete-course':data.courses=data.courses.filter(x=>x.id!==id);break;case'delete-od':data.ods=data.ods.filter(x=>x.id!==id);break;case'delete-class':data.schedule=data.schedule.filter(x=>x.id!==id);break;case'disable-reminders':data.settings.reminders=false;break;default:return;}save();render();}
  function odDuration(hours,details=[]){return details.length===1?`HOUR ${details[0].period}`:hours===1?'1 HR':hours>1?`${hours} HRS`:'FULL DAY · HOURS NOT MAPPED';}
  function attendanceMark(status){const value=String(status||'').trim().toLowerCase();if(['present','attended','true','1'].includes(value))return {label:'Present',className:'present'};if(['absent','missed','false','0'].includes(value))return {label:'Absent',className:'absent'};return {label:status||'Unconfirmed',className:''};}
  function recentOdPreview(){return [...data.ods].sort((a,b)=>b.start.localeCompare(a.start)).slice(0,3).map(o=>`<div class="od-preview-row"><div><b>${esc(o.type)}</b><small>${fmtRange(o.start,o.end)}</small></div><span class="status-pill ${o.status.toLowerCase()}">${esc(o.status)}</span><span class="od-duration-preview">${odDuration(o.hours,o.details)}</span></div>`).join('');}
  function empty(title,copy,action='Add course',actionId='add-course') {return `<div class="empty-panel"><h3>${title}</h3><p>${copy}</p><div class="empty-actions"><button class="button button-primary" data-action="${actionId}">${action}</button><button class="button button-quiet" data-action="connect">MyCamu connection</button></div></div>`;}
  function courseMarkup(c,compact=false){const p=coursePercent(c),miss=safeMiss(c),need=recover(c),n1=miss==null?'—':miss,n2=need==null?'—':need===Infinity?'—':need;return `<article class="${compact?'course-row':'course-card'}"><div class="course-info"><b>${esc(c.name)}</b><small>${esc(c.code||'Course')} · ${c.attended} / ${c.total} classes</small></div><div class="course-stat"><strong>${fmtPct(p)}</strong><small>${esc(courseStatus(c))}</small></div>${compact?`<div class="course-guidance"><span>Can miss <strong>${n1}</strong></span><span>·</span><span>Must attend <strong class="${n2==='—'?'':n2?'risk-text':'safe-text'}">${n2}</strong></span></div>`:`<div class="course-data"><div class="data-cell"><span>Can miss</span><b>${n1} ${n1===1?'class':'classes'}</b></div><div class="data-cell"><span>Must attend</span><b class="${n2==='—'?'':n2?'risk-text':'safe-text'}">${n2} ${n2===1?'class':'classes'}</b></div></div><div class="course-explainer">${esc(need===Infinity?'A 100% target can’t be recovered after a missed class.':need?`Attend the next ${need} classes to reach your target.`:miss===0?'One missed class would put you below target.':`You can miss ${miss} more ${miss===1?'class':'classes'} and stay at your target.`)}</div><div class="course-actions"><button class="button button-quiet" data-edit-course="${esc(c.id)}">Edit counts</button>${holdButton('Hold to remove','delete-course',c.id,`Hold to remove ${c.name}`)}</div>`}</article>`;}
  function overall(){const attended=data.courses.reduce((n,c)=>n+c.attended,0),total=data.courses.reduce((n,c)=>n+c.total,0);return {attended,total,percent:total?100*attended/total:null};}
  function nextExam(){const now=new Date();now.setHours(0,0,0,0);return data.exams.map(item=>({item,date:new Date(Number(item.startsAt))})).filter(x=>Number.isFinite(x.date.getTime())&&x.date>=now).sort((a,b)=>a.date-b.date).map(x=>({...x,days:Math.ceil((x.date-now)/86400000)}))[0]||null;}
  function marks(){const gradePoint={O:10,S:10,'A+':9,A:8,'B+':7};const grouped=new Map();for(const row of data.academicRecords){const sem=String(row.semester||'Semester');if(!grouped.has(sem))grouped.set(sem,[]);grouped.get(sem).push(row);}let allPoints=0,allCredits=0;const semesters=[...grouped.entries()].map(([name,rows])=>{let points=0,credits=0;for(const row of rows){const c=num(row.credits),g=gradePoint[String(row.grade||'').toUpperCase()];if(c>0&&g!=null){points+=c*g;credits+=c;}}allPoints+=points;allCredits+=credits;return `<section class="panel marks-semester"><div class="panel-head"><h2>${esc(name)}</h2><strong class="semester-gpa">${credits?(points/credits).toFixed(2):'—'}<small>SGPA</small></strong></div><div class="marks-list">${rows.map(row=>`<article class="marks-row"><div><b>${esc(row.name||row.code||'Course')}</b><small>${esc(row.code||'')}</small></div><span>${esc(row.credits||0)} cr</span><strong class="grade-pill">${esc(row.grade||'—')}</strong></article>`).join('')}</div></section>`;});return `<section class="panel internal-marks-panel"><div class="panel-head"><h2>Internal assessments</h2></div><div class="panel-body">${data.internalMarks.length?data.internalMarks.map(row=>`<div class="marks-row"><div><b>${esc(row.course)}</b><small>${esc([row.semester,row.assessment,row.date].filter(Boolean).join(' · '))}</small></div><strong class="grade-pill">${row.scoreAvailable?`${row.score} / ${row.maximum}`:esc(row.status[0].toUpperCase()+row.status.slice(1))}</strong></div>`).join(''):`<p class="empty-copy">No internal marks synced. KCT’s portal lists internal marks, but Rollcall has no verified student-facing data feed yet.</p>`}</div></section><div class="page-head"><div><h1>Marks &amp; academics</h1><p>Course grades and semester performance from the KCT portal.</p></div>${data.academicUpdatedAt?`<span class="status-pill">Updated ${new Date(Number(data.academicUpdatedAt)).toLocaleDateString()}</span>`:''}</div>${data.academicRecords.length?`<section class="panel cgpa-panel"><span class="section-label">CUMULATIVE GPA</span><strong>${allCredits?(allPoints/allCredits).toFixed(2):'—'}</strong><p>${allCredits} graded credits · zero-credit domains are excluded.</p></section><div class="marks-semesters">${semesters.join('')}</div>`:`<div class="empty-panel"><h3>No KCT results synced yet</h3><p>Sign in to the KCT portal in the Rollcall app and let it finish collecting completed-course results.</p></div>`}`;}
  function home(){
    const o=overall(),low=data.courses.filter(c=>coursePercent(c)!=null&&coursePercent(c)<data.target).sort((a,b)=>coursePercent(a)-coursePercent(b));
    const now=new Date(),nowKey=`${dayKey(now)}T${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
    const upcoming=data.schedule.filter(e=>`${e.date}T${e.time||'00:00'}`>=nowKey).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];
    const week=startWeek(0),days=Array.from({length:7},(_,i)=>{const d=new Date(week);d.setDate(d.getDate()+i);const key=dayKey(d),count=data.schedule.filter(e=>e.date===key).length;return `<div class="week-day ${count?'has-classes':''}"><span>${d.toLocaleDateString(undefined,{weekday:'short'})}</span><b>${d.getDate()}</b>${count?`<small>${count} ${count===1?'class':'classes'}</small>`:''}</div>`;}).join('');
    const approved=data.ods.filter(o=>o.status==='Approved').length,pending=data.ods.filter(o=>o.status==='Pending').length;
    const exam=nextExam();
    return `<section class="home-intro"><div><h1>${data.name?`Good to see you, ${esc(data.name)}.`:'Make every class count.'}</h1><p>Attendance, schedule and on-duty details in one place · ${new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p></div><div class="home-controls"><div class="sync-box"><i class="status-dot"></i><span>${remoteMode?'Phone synced · read only':'Browser data · saved locally'}</span></div><button class="pull-cord" type="button" data-pull-cord data-pulling="${modePulling}" aria-pressed="${data.settings.dark}" aria-label="${data.settings.dark?'Switch to light mode':'Switch to dark mode'}"><span class="pull-line" aria-hidden="true"></span><span class="pull-knob" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20.5 15.5A8.5 8.5 0 0 1 8.5 3.5 8.5 8.5 0 1 0 20.5 15.5Z"/></svg></span><span class="pull-copy"><b>Appearance</b><small>${data.settings.dark?'Dark mode':'Light mode'} · pull to switch</small></span></button></div></section>
      <div class="home-grid"><div class="home-main">
        <section class="panel attendance-panel"><div class="attendance-top"><div><h2>Your attendance</h2><p>${o.total?`${o.attended} of ${o.total} classes attended across ${data.courses.length} courses.`:'Add your course counts to see where you stand.'}</p></div>${targetBanner()}</div><div class="attendance-overall"><strong>${fmtPct(o.percent)}</strong><span>${o.percent==null?'No class data yet':o.percent>=data.target?'overall · on target':'overall · below target'}</span></div><div class="attendance-counts">${o.total?`${o.total-o.attended} classes missed · ${o.attended} attended`:'Your records stay in this browser.'}</div><div class="attendance-meter"><i style="--value:${o.percent||0}%"></i></div><div class="meter-labels"><span>0%</span><b>${data.target}% target</b><span>100%</span></div></section>
        <section class="panel"><div class="panel-head"><h2>Courses to watch</h2><button class="panel-link" data-go="courses">All courses →</button></div><div class="panel-body">${low.length?`<div class="course-list">${low.slice(0,4).map(c=>courseMarkup(c,true)).join('')}</div>`:data.courses.length?`<p class="empty-copy">All courses are at or above your target.</p>`:empty('Your course list starts here','Add attendance counts from MyCamu or import a Rollcall backup to get your miss/attend guidance.')}</div></section>
        <section class="panel">${sectionHead('This week','Full week','week')}<div class="panel-body"><div class="weekly-peek">${days}</div>${!data.schedule.length?`<p class="empty-copy">No timetable added yet. Add classes in Week when you have your schedule.</p>`:''}</div></section>
      </div><div class="home-side">
        <section class="panel next-class">${upcoming?`<h2>Next class · ${esc(upcoming.name)}</h2><p>${fmtDay(upcoming.date)} · ${esc(upcoming.time||'Time not set')}${upcoming.endTime?`–${esc(upcoming.endTime)}`:''}</p><div class="class-meta"><span>${esc(upcoming.code||'Course')}</span><span>${esc(upcoming.location||'Location not set')}</span></div>`:`<h2>${data.schedule.length?'No upcoming class':'Timetable not added'}</h2><p>${data.schedule.length?'Your saved schedule has no upcoming classes.':'Add your weekly classes in Week.'}</p><div class="empty-actions"><button class="button button-secondary" data-go="week">Open Week</button></div>`}</section>
        ${exam?`<section class="panel upcoming-exam"><span class="section-label">UPCOMING EXAM</span><div class="exam-countdown"><strong>${exam.days}</strong><span>${exam.days===1?'day':'days'} to go</span></div><h2>${esc(exam.item.title||exam.item.course||'Exam')}</h2><p class="exam-course">${esc(exam.item.course||'Course not specified')}</p><div class="class-meta"><span class="exam-type">${esc(exam.item.type||'Exam')}</span><span class="exam-session ${exam.item.session==='FN'?'fn':'an'}">${esc(exam.item.session||'Session not set')}</span><span class="exam-date">${fmtDay(exam.date)}</span></div></section>`:''}
        <section class="panel">${sectionHead('Leave & OD','View all','od')}<div class="panel-body">${data.ods.length?`<div class="od-summary-row"><span><b class="green">${approved}</b> approved</span><span><b class="amber">${pending}</b> pending</span><span>${data.ods.length} total</span></div><div class="od-preview-list">${recentOdPreview()}</div>`:`<p class="empty-copy">No leave or OD records in this browser yet.</p>`}</div></section>
        <section class="panel">${sectionHead(remoteMode?'Phone sync':'MyCamu data') }<div class="panel-body"><p class="empty-copy">${remoteMode?'This read-only view refreshes from the Rollcall app while your phone syncs. KCT marks and exams update after you open the KCT portal in the app.':data.settings.mycamuImportedAt?'A MyCamu snapshot was imported into this browser.':'Direct MyCamu sync is unavailable in this browser. Use the Rollcall app to sync MyCamu data, then sign into your Rollcall web account.'}</p>${remoteMode?'':`<button class="button button-quiet" data-action="connect">MyCamu sign-in details</button>`}</div></section>
      </div></div>`;
  }
  function courses(){let list=data.courses.filter(c=>`${c.name} ${c.code}`.toLowerCase().includes(courseQuery.toLowerCase()));if(courseFilter==='below')list=list.filter(c=>coursePercent(c)!=null&&coursePercent(c)<data.target);if(courseFilter==='on')list=list.filter(c=>coursePercent(c)!=null&&coursePercent(c)>=data.target);return `<div class="page-head"><div><h1>Can I miss a class?</h1><p>Your attendance and target guidance, course by course.</p></div><button class="button button-primary" data-action="add-course">Add course +</button></div><div class="toolbar"><div class="toolbar-left"><div class="segmented"><button data-course-filter="all" aria-pressed="${courseFilter==='all'}">All ${data.courses.length}</button><button data-course-filter="below" aria-pressed="${courseFilter==='below'}">Below target</button><button data-course-filter="on" aria-pressed="${courseFilter==='on'}">On target</button></div></div><input class="search-input" id="course-search" type="search" placeholder="Search courses" value="${esc(courseQuery)}" aria-label="Search courses"></div><div class="course-page-list">${list.length?list.map(c=>courseMarkup(c)).join(''):empty(data.courses.length?'No courses match':'No courses yet',data.courses.length?'Try a different search or filter.':'Add a course or import your Rollcall backup.')}</div>`;}
  function week(){const start=startWeek(weekShift),days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d;}),day=days[selectedDay]||days[0],events=data.schedule.filter(e=>e.date===dayKey(day)).sort((a,b)=>a.time.localeCompare(b.time));const history=data.history.filter(x=>!x.date||x.date===dayKey(day));return `<div class="page-head"><div><h1>Your week</h1><p>See your classes and attendance history.</p></div><button class="button button-primary" data-action="add-class">Add class +</button></div><div class="week-layout"><section class="panel"><div class="panel-body"><div class="week-toolbar"><button class="icon-button" data-action="week-prev" aria-label="Previous week">‹</button><h2>${start.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><button class="icon-button" data-action="week-next" aria-label="Next week">›</button></div><div class="weekly-peek">${days.map((d,i)=>`<button class="week-day ${selectedDay===i?'has-classes':''}" data-select-day="${i}"><span>${d.toLocaleDateString(undefined,{weekday:'short'})}</span><b>${d.getDate()}</b>${data.schedule.some(e=>e.date===dayKey(d))?'<small>Class</small>':''}</button>`).join('')}</div><div class="week-toolbar" style="margin-top:24px"><h2>${day.toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long'})}</h2><span class="status-pill">${events.length} ${events.length===1?'class':'classes'}</span></div>${events.length?`<div class="schedule-list">${events.map(e=>`<div class="schedule-item"><div><span class="schedule-time">${esc(e.time||'—')}${e.endTime?`–${esc(e.endTime)}`:''}</span><span class="schedule-date">${esc(e.code||'')}</span></div><div><div class="schedule-name">${esc(e.name)}</div><div class="schedule-meta">${esc(e.location||'Location not set')}</div></div>${holdButton('Hold to remove','delete-class',e.id,`Hold to remove ${e.name}`)}</div>`).join('')}</div>`:empty('No classes on this day','Add schedule items to make the week view useful.','Add class','add-class')}</div></section><aside class="home-side"><section class="panel">${sectionHead('Attendance history')}<div class="panel-body">${history.length?`<div class="event-list">${history.map(h=>{const mark=attendanceMark(h.status);return `<div class="event-row"><div class="event-time">${esc(h.time||fmtDay(h.date||dayKey(day)))}</div><div><b>${esc(h.name||'Class')}</b><small class="attendance-mark ${mark.className}">${esc(mark.label)}</small></div></div>`;}).join('')}</div>`:`<p class="empty-copy">Class marks will appear here after they are imported with your data.</p>`}</div></section><div class="notice">Schedule and attendance saved here do not refresh from MyCamu automatically.</div></aside></div>`;}
  function whatif(){const c=data.courses[0],id=c?.id||'',p=c?coursePercent(c):null;return `<div class="page-head"><div><h1>What if?</h1><p>Estimate how attending or missing classes changes your course target.</p></div>${targetBanner()}</div>${c?`<div class="whatif-layout"><section class="panel planner"><label for="planner-course">Course</label><select id="planner-course">${data.courses.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${fmtPct(coursePercent(x))}</option>`).join('')}</select><div class="choice-row"><button class="${window.planAction!=='miss'?'selected':''}" data-plan-action="attend">Attend</button><button class="${window.planAction==='miss'?'selected':''}" data-plan-action="miss">Miss</button></div><div class="count-control"><button data-plan-count="-1" aria-label="Decrease class count">−</button><output id="plan-count">${window.planCount||1}</output><button data-plan-count="1" aria-label="Increase class count">+</button></div><button class="button button-primary" id="run-plan">Update estimate</button><p class="empty-copy">Estimate only. This does not change your attendance record.</p></section><section class="panel projection"><h2>Projected attendance</h2><div class="projected-percent" id="projected-percent">${fmtPct(p)}</div><p id="projected-copy">${c.attended} attended out of ${c.total} classes · ${courseStatus(c)}</p><div class="projection-rule"><i id="projection-fill" style="width:${p||0}%"></i></div><div class="meter-labels"><span>0%</span><b>${data.target}% target</b><span>100%</span></div><p id="projected-guidance">${p!=null&&p>=data.target?'You are currently at or above target.':'Check how many classes you need to attend to recover.'}</p></section></div>`:empty('Add attendance counts first','What If uses a course’s current attended and total classes to estimate the result.','Add course','add-course')}`;}
  function odCard(o){const expanded=window.expandedOd===o.id, span=Math.max(1,Math.round((parseDay(o.end)-parseDay(o.start))/86400000)+1),duration=odDuration(o.hours,o.details);const badge=o.status.toLowerCase();return `<article class="od-card"><div class="od-card-head" role="button" tabindex="0" aria-expanded="${expanded}" data-toggle-od="${esc(o.id)}"><h3>${esc(o.type)}</h3><span class="status-pill ${badge}">${esc(o.status)}</span><span class="panel-link" aria-hidden="true">${expanded?'−':'+'}</span></div><p class="od-date">${fmtRange(o.start,o.end)}</p><div class="od-duration">${duration}</div>${expanded?`<div class="od-details">${Array.from({length:Math.min(span,31)},(_,i)=>{const d=parseDay(o.start);d.setDate(d.getDate()+i);const key=dayKey(d),slots=(o.details||[]).filter(x=>x.date===key);return `<h4>${d.toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'short',year:'numeric'})}</h4>${slots.length?slots.map(x=>`<div class="od-slot"><span>Hour ${x.period}${x.time?` · ${esc(x.time)}`:''}${x.endTime?`–${esc(x.endTime)}`:''}${x.name?` · ${esc(x.name)}`:''}</span><b>Scheduled</b></div>`).join(''):`<div class="od-slot"><span>${o.hours?`On Duty · ${o.hours===1?'1 hour':`${o.hours} hours`}`:'Full day · no mapped hours'}</span>${o.hours?'<b>Scheduled</b>':''}</div>`}`;}).join('')}<div class="course-actions">${holdButton('Hold to remove record','delete-od',o.id,`Hold to remove ${o.type} record`)}</div></div>`:''}</article>`;}
  function od(){const rows=data.ods.filter(o=>odFilter==='all'||o.currentSemester);const counts={approved:data.ods.filter(o=>o.status==='Approved').length,pending:data.ods.filter(o=>o.status==='Pending').length,rejected:data.ods.filter(o=>o.status==='Rejected').length};return `<div class="page-head"><div><h1>Leave &amp; OD</h1><p>Review approval status, covered dates, and scheduled hours.</p></div><button class="button button-primary" data-action="add-od">Add record +</button></div><div class="od-filters"><div class="segmented"><button data-od-filter="current" aria-pressed="${odFilter==='current'}">Current sem · ${data.ods.filter(o=>o.currentSemester).length}</button><button data-od-filter="all" aria-pressed="${odFilter==='all'}">All records · ${data.ods.length}</button></div></div><div class="od-summary-row" style="margin:0 0 15px"><span><b class="green">${counts.approved}</b> approved</span><span><b class="amber">${counts.pending}</b> pending</span><span><b class="red">${counts.rejected}</b> rejected</span></div><div class="od-card-list">${rows.length?rows.map(odCard).join(''):empty('No OD records in this view','Add a record or switch to all records to review older items.','Add record','add-od')}</div>`;}
  function settings(){
    const pages={root:{title:'Settings'},profile:{title:'Profile'},target:{title:'Attendance target'},reminders:{title:'Class reminders'},appearance:{title:'Appearance'},mycamu:{title:'MyCamu account'},data:{title:'Your data'}};
    const key=settingsStack[settingsStack.length-1]||'root',page=pages[key]||pages.root,parent=settingsStack.length>1?pages[settingsStack[settingsStack.length-2]]:null,nextReminder=nextTimedClass();
    const row=(label,detail,to)=>`<button class="stack-row" type="button" data-settings-open="${to}"><span>${label}</span><span class="stack-detail">${esc(detail)}</span><span class="stack-chevron" aria-hidden="true">›</span></button>`;
    let body='';
    if(key==='root') body=`<div class="stack-sections"><section class="stack-section"><h2>ACCOUNT</h2>${row('Profile',data.name||'My Rollcall','profile')}${row('Attendance target',`${data.target}%`,'target')}</section><section class="stack-section"><h2>PREFERENCES</h2>${row('Class reminders',remindersOn()?'Enabled':'Off','reminders')}${row('Appearance',`${data.settings.palette==='signal'?'Signal':data.settings.palette} · ${data.settings.appearance==='system'?'System':isDarkMode()?'Dark':'Light'}`,'appearance')}</section><section class="stack-section"><h2>CONNECTION & DATA</h2>${row('MyCamu account',data.settings.mycamuImportedAt?'Imported':'Not connected','mycamu')}${row('Your data','Export or import a backup','data')}</section></div>`;
    else if(key==='profile') body=`<section class="stack-section stack-detail-page"><h2>YOUR PROFILE</h2><label>Display name<input id="setting-name" maxlength="60" value="${esc(data.name)}" placeholder="Your name"></label><p class="stack-footnote">This name is stored only in this browser.</p><button class="button button-primary" id="save-profile">Save name</button></section>`;
    else if(key==='target') body=`<section class="stack-section stack-detail-page"><h2>ATTENDANCE GUIDANCE</h2><label>Attendance target (%)<input id="setting-target" type="number" min="1" max="100" value="${data.target}"></label><p class="stack-footnote">Use the minimum attendance target that applies to your courses.</p><button class="button button-primary" id="save-target">Save target</button></section>`;
    else if(key==='reminders') body=`<section class="stack-section stack-detail-page"><h2>CLASS REMINDERS</h2>${remindersOn()?`<button class="bell-toggle is-on" type="button" aria-pressed="true" aria-label="Class notifications are enabled" disabled><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span>Reminders enabled</span></button>${holdButton('Hold to turn off reminders','disable-reminders','', 'Hold to turn off class reminders')}`:`<button class="bell-toggle" type="button" data-enable-notifications aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span class="bell-label-off">Notify me</span><span class="bell-label-on">Notifications enabled</span></button>`}<p class="stack-footnote">${remindersOn()?(nextReminder?`Next reminder: 10 minutes before ${esc(nextReminder.event.name)} at ${esc(nextReminder.event.time)}.`:'No upcoming class with a start time is saved yet. Add one in Week to schedule a reminder.'):'Allow browser notifications for a reminder 10 minutes before classes in your saved timetable.'} Keep Rollcall open for reminders.</p><p class="notification-feedback" id="notification-feedback" role="status" aria-live="polite">${'Notification'in window?(Notification.permission==='denied'?'Notifications are blocked in browser settings.':remindersOn()?'Browser permission is on.':'Browser permission is not enabled yet.'):'This browser does not support notifications.'}</p></section>`;
    else if(key==='appearance') body=`<section class="stack-section"><h2>COLOR APPEARANCE</h2><p class="stack-footnote">Choose how Rollcall responds to your device’s appearance.</p><div class="appearance-modes" role="group" aria-label="Appearance mode">${[['light','Light'],['dark','Dark'],['system','System']].map(([id,label])=>`<button type="button" data-appearance-mode="${id}" aria-pressed="${(data.settings.appearance||'light')===id}">${label}</button>`).join('')}</div><h3>COLOR PALETTE</h3><div class="palette-picker" role="group" aria-label="Color palette">${[['signal','Signal'],['cobalt','Cobalt Studio'],['copper','Copper Night'],['forest','Forest Circuit'],['paper','Paper Circuit']].map(([id,name])=>`<button class="palette-choice" type="button" data-color-palette="${id}" aria-pressed="${(data.settings.palette||'signal')===id}"><span class="palette-swatch ${id}" aria-hidden="true"></span>${name}</button>`).join('')}</div></section>`;
    else if(key==='mycamu') body=`<section class="stack-section stack-detail-page"><h2>MYCAMU</h2><p class="stack-footnote">${remoteMode?'The MyCamu data shown here is mirrored from your Rollcall phone. The phone syncs MyCamu; this website does not ask for your MyCamu password.':data.settings.mycamuImportedAt?'Last imported snapshot · '+new Date(data.settings.mycamuImportedAt).toLocaleString()+'.':'Rollcall does not sign in to MyCamu directly in this browser.'}</p>${remoteMode?'':`<button class="button button-secondary" data-action="connect">Open MyCamu</button>`}</section>`;
    else body=`<section class="stack-section stack-detail-page"><h2>BACKUP THIS BROWSER</h2><p class="stack-footnote">Your courses and attendance entries are stored only in this browser. Export a backup before moving to another device.</p><div class="empty-actions"><button class="button button-secondary" data-action="export">Export backup</button><button class="button button-quiet" data-action="import">Import backup</button><input class="file-input" id="import-file" type="file" accept="application/json,.json"></div></section>`;
    return `<section class="stack-panel" id="settings-stack" data-direction="${settingsDirection}"><header class="stack-header">${parent?`<button class="stack-back" type="button" id="settings-back" aria-label="Back to ${esc(parent.title)}"><span aria-hidden="true">‹</span>${esc(parent.title)}</button>`:''}<h1>${esc(page.title)}</h1></header><div class="stack-page" key="${key}">${body}</div></section>`;
  }
  function render(){updateChrome();main.innerHTML=({home,courses,week,whatif,od,marks,settings})[screen]();bind();}
  function bind(){
    main.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>setScreen(b.dataset.go)));
    main.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));
    main.querySelectorAll('[data-course-filter]').forEach(b=>b.addEventListener('click',()=>{courseFilter=b.dataset.courseFilter;render();}));
    main.querySelectorAll('[data-od-filter]').forEach(b=>b.addEventListener('click',()=>{odFilter=b.dataset.odFilter;render();}));
    main.querySelectorAll('[data-select-day]').forEach(b=>b.addEventListener('click',()=>{selectedDay=Number(b.dataset.selectDay);render();}));
    main.querySelectorAll('[data-toggle-od]').forEach(b=>{const toggle=()=>{window.expandedOd=window.expandedOd===b.dataset.toggleOd?'':b.dataset.toggleOd;render();};b.addEventListener('click',toggle);b.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle();}});});
    main.querySelectorAll('[data-edit-course]').forEach(b=>b.addEventListener('click',()=>editCourse(b.dataset.editCourse)));
    main.querySelectorAll('.hold-action').forEach(b=>{let timer=0,completed=false;const cancel=()=>{clearTimeout(timer);if(!completed){b.classList.remove('holding');const label=b.querySelector('.hold-label');if(label)label.textContent=b.dataset.holdLabel||'Hold to confirm';}};const start=e=>{if(e.type==='pointerdown'&&e.button!==0)return;if(e.type==='keydown'&&(e.repeat||![' ','Enter'].includes(e.key)))return;if(e.cancelable)e.preventDefault();if(e.type==='pointerdown')b.setPointerCapture?.(e.pointerId);completed=false;b.classList.add('holding');const label=b.querySelector('.hold-label');if(label)label.textContent='Keep holding…';timer=setTimeout(()=>{completed=true;b.classList.remove('holding');b.classList.add('completed');completeHold(b);},900);};b.dataset.holdLabel=b.querySelector('.hold-label')?.textContent||'Hold to confirm';b.addEventListener('pointerdown',start);b.addEventListener('pointerup',cancel);b.addEventListener('pointercancel',cancel);b.addEventListener('keydown',start);b.addEventListener('keyup',cancel);b.addEventListener('blur',cancel);});
    const search=main.querySelector('#course-search');if(search)search.addEventListener('input',()=>{courseQuery=search.value;const pos=search.selectionStart;main.innerHTML=courses();bind();const next=main.querySelector('#course-search');next.focus();next.setSelectionRange(pos,pos);});
    main.querySelectorAll('[data-plan-action]').forEach(b=>b.addEventListener('click',()=>{window.planAction=b.dataset.planAction;render();}));
    main.querySelectorAll('[data-plan-count]').forEach(b=>b.addEventListener('click',()=>{window.planCount=Math.max(1,Math.min(100,Number(window.planCount||1)+Number(b.dataset.planCount)));render();}));
    const run=main.querySelector('#run-plan');if(run)run.addEventListener('click',runProjection);
    const pushSettings=key=>{if(!['profile','target','reminders','appearance','mycamu','data'].includes(key))return;settingsStack.push(key);settingsDirection='forward';render();};
    main.querySelectorAll('[data-settings-open]').forEach(b=>b.addEventListener('click',()=>pushSettings(b.dataset.settingsOpen)));
    const backSettings=()=>{if(settingsStack.length<2)return;settingsStack.pop();settingsDirection='back';render();};
    main.querySelector('#settings-back')?.addEventListener('click',backSettings);
    main.onkeydown=e=>{if(e.key==='Escape'&&screen==='settings'&&settingsStack.length>1){e.preventDefault();backSettings();}};
    const stackPanel=main.querySelector('#settings-stack');if(stackPanel){stackPanel.addEventListener('touchstart',e=>{settingsTouchX=e.target.closest('input,button,select,textarea')?null:e.changedTouches[0].clientX;},{passive:true});stackPanel.addEventListener('touchend',e=>{if(settingsTouchX!=null&&e.changedTouches[0].clientX-settingsTouchX>90)backSettings();settingsTouchX=null;},{passive:true});}
    main.querySelector('[data-enable-notifications]')?.addEventListener('click',e=>enableNotifications(e.currentTarget));
    main.querySelector('[data-pull-cord]')?.addEventListener('click',e=>toggleTheme(e.currentTarget));
    main.querySelector('[data-theme-switch]')?.addEventListener('click',e=>toggleTheme(e.currentTarget));
    main.querySelectorAll('[data-color-palette]').forEach(b=>b.addEventListener('click',()=>{data.settings.palette=b.dataset.colorPalette;save();render();}));
    main.querySelectorAll('[data-appearance-mode]').forEach(b=>b.addEventListener('click',()=>{data.settings.appearance=b.dataset.appearanceMode;data.settings.dark=isDarkMode();save();render();}));
    const saveName=main.querySelector('#save-profile');if(saveName)saveName.addEventListener('click',()=>{data.name=main.querySelector('#setting-name').value.trim().slice(0,60);save();render();});
    const saveTarget=main.querySelector('#save-target');if(saveTarget)saveTarget.addEventListener('click',()=>{const target=num(main.querySelector('#setting-target').value);if(target<1||target>100){alert('Choose a target from 1% to 100%.');return;}data.target=target;save();render();});
    const imp=main.querySelector('#import-file');if(imp)imp.addEventListener('change',importFile);
  }
  function openConnectionDialog(){document.querySelector('#connect-dialog').showModal();}
  function action(name){if(name==='add-course'){openCourse();return;}if(name==='add-od'){openOd();return;}if(name==='add-class'){openClass();return;}if(name==='connect'){openConnectionDialog();return;}if(name==='export'){exportData();return;}if(name==='import'){main.querySelector('#import-file')?.click();}}
  function openCourse(existing){const dlg=document.querySelector('#course-dialog'),form=document.querySelector('#course-form'),item=existing&&data.courses.find(c=>c.id===existing);form.reset();document.querySelector('#course-dialog-title').textContent=item?'Edit course':'Add a course';if(item)for(const k of ['name','code','attended','total'])form.elements[k].value=item[k];form.dataset.edit=item?.id||'';dlg.showModal();}
  function editCourse(id){openCourse(id);}
  document.querySelector('#course-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),attended=num(fd.get('attended')),total=num(fd.get('total')),name=String(fd.get('name')||'').trim();if(!name||attended<0||total<attended){alert('Enter a course name and valid attended / total counts.');return;}const item={id:f.dataset.edit||crypto.randomUUID(),name,code:String(fd.get('code')||'').trim(),attended,total};const at=data.courses.findIndex(c=>c.id===item.id);if(at<0)data.courses.push(item);else data.courses[at]=item;save();f.closest('dialog').close();render();});
  function openOd(){const f=document.querySelector('#od-form');f.reset();const today=dayKey(new Date());f.elements.start.value=today;f.elements.end.value=today;f.elements.hours.value='1';document.querySelector('#od-dialog').showModal();}
  document.querySelector('#od-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),start=String(fd.get('start')),end=String(fd.get('end')),hours=num(fd.get('hours'));if(end<start||hours<0||hours>120){alert('Check the date range and hour count.');return;}data.ods.unshift({id:crypto.randomUUID(),type:String(fd.get('type')),status:String(fd.get('status')),start,end,hours,currentSemester:fd.has('currentSemester')});save();e.currentTarget.closest('dialog').close();render();});
  function openClass(){const form=document.querySelector('#class-form');form.reset();form.elements.date.value=dayKey(startWeek(weekShift));document.querySelector('#class-dialog').showModal();}
  document.querySelector('#class-form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),name=String(fd.get('name')||'').trim(),date=String(fd.get('date')),time=String(fd.get('time')||''),endTime=String(fd.get('endTime')||'');if(!name||!date||(time&&endTime&&endTime<=time)){alert('Enter a class name, date, and a valid time range.');return;}data.schedule.push({id:crypto.randomUUID(),date,time,endTime,name,code:String(fd.get('code')||'').trim(),location:String(fd.get('location')||'').trim()});save();e.currentTarget.closest('dialog').close();render();});
  function runProjection(){const c=data.courses.find(x=>x.id===main.querySelector('#planner-course').value);if(!c)return;const count=Math.max(1,Number(window.planCount||1)),attended=c.attended+(window.planAction==='miss'?0:count),total=c.total+count,percent=total?100*attended/total:null,need=percent!=null&&percent<data.target?(data.target===100?Infinity:Math.ceil((data.target*total-100*attended)/(100-data.target))):0;main.querySelector('#projected-percent').textContent=fmtPct(percent);main.querySelector('#projected-copy').textContent=`${attended} attended out of ${total} classes · ${percent>=data.target?'On target':'Below target'}`;main.querySelector('#projection-fill').style.width=`${percent||0}%`;main.querySelector('#projected-guidance').textContent=percent>=data.target?'You would remain at or above your target.':need===Infinity?'A 100% target can’t be recovered after a missed class.':`Attend ${need} more classes in a row to reach your target.`;}
  function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rollcall-backup.json';a.click();URL.revokeObjectURL(url);}
  async function importFile(e){const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){alert('Backups must be smaller than 2 MB.');e.target.value='';return;}try{const parsed=normalize(JSON.parse(await file.text()));if(!confirm(`Replace this browser’s Rollcall data with ${parsed.courses.length} courses and ${parsed.ods.length} OD records?`))return;data=parsed;save();render();alert('Rollcall backup imported.');}catch(err){alert(err.message||'This file could not be imported.');}finally{e.target.value='';}}
  document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog')?.close()));
  document.querySelector('#open-mycamu').addEventListener('click',()=>window.open('https://www.mycamu.co.in/v2/attendance','_blank','noopener,noreferrer'));
  document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>setScreen(b.dataset.screen)));
  document.querySelector('#add-course-top').addEventListener('click',()=>action('add-course'));
  document.querySelector('#course-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
  document.querySelector('#od-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
  document.querySelector('#connect-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close();});
  window.addEventListener('rollcall-cloud-snapshot',event=>{const dark=isDarkMode(),appearance=data.settings.appearance,palette=data.settings.palette||'signal',s=event.detail||{},date=ms=>{const n=Number(ms),d=new Date(n);return n>0&&Number.isFinite(d.getTime())?dayKey(d):'';};const time=ms=>{const d=new Date(Number(ms));return Number.isFinite(d.getTime())?`${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`:'';};const snapshot={version:1,target:s.target,name:s.name,courses:(s.courses||[]).filter(c=>c.countsKnown!==false).map(c=>({name:c.name,code:c.code,attended:c.attended,total:c.total})),schedule:(s.timetable||[]).filter(e=>!e.cancelled&&Number(e.startsAt)>0).map(e=>({id:e.id,date:date(e.startsAt),time:e.allDay?'':time(e.startsAt),endTime:e.allDay?'':time(e.endsAt),name:e.name,code:e.code,location:e.location})),ods:(s.leaves||[]).filter(o=>Number(o.startsAt)>0).map(o=>({id:o.id,type:o.type,status:o.status,start:date(o.startsAt),end:date(o.endsAt),hours:o.periods,currentSemester:o.currentSemester,details:(()=>{try{return JSON.parse(o.periodDetails||'[]').map(x=>({...x,date:x.date||date(x.startsAt)||date(o.startsAt)}));}catch{return [];}})()})),history:(s.classMarks||[]).filter(x=>Number(x.startsAt)>0).map(x=>({id:x.id,name:x.name,code:x.code,date:date(x.startsAt),time:time(x.startsAt),status:x.status})),academicRecords:s.academicRecords||[],internalMarks:s.internalMarks||[],exams:s.exams||[],academicUpdatedAt:s.academicUpdatedAt,settings:{dark,reminders:false,mycamuImportedAt:new Date(Number(s.updatedAt||Date.now())*1000).toISOString()}};try{data=normalize(snapshot);data.settings.dark=dark;data.settings.appearance=appearance;data.settings.palette=palette;remoteMode=true;document.body.classList.add('remote-data');document.body.dataset.palette=palette;render();}catch(error){console.error('Could not read the synced Rollcall snapshot.',error);}});
  window.addEventListener('rollcall-cloud-logout',()=>{remoteMode=false;document.body.classList.remove('remote-data');load();render();});
  window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(screens[next])setScreen(next);});
  if('serviceWorker' in navigator && location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').then(reg=>{notificationRegistration=reg;scheduleClassReminder();}).catch(()=>{});
  load();render();scheduleClassReminder();
  matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(data.settings.appearance==='system'){updateChrome();if(!remoteMode)save();}});
})();
